test "glyph masks are nonblank and indexable" {
    // Guards the shift-overflow that used to crash inspect: the old 1-bit
    // table was only 8 bits tall while glyph_height claimed 16, and the draw
    // loop shifted 0x8000 by up to 15 places into a u8, a Debug-mode panic.
    // Alpha-column format: glyphs[g][c*glyph_height + row] in 0..255.
    var set: u32 = 0;
    for (glyphs, 0..) |glyph, gi| {
        if (gi == 0) continue; // space may be blank
        for (0..glyph_width) |c| {
            var r: usize = 0;
            while (r < glyph_height) : (r += 1) {
                if (glyph[c * glyph_height + r] != 0) set += 1;
            }
        }
        if (set == 0) @panic("no pixels");
        set = 0;
    }
    try std.testing.expectEqual(glyph_width, 10);
    try std.testing.expectEqual(glyph_height, 16);
}
